func TestFrozenEnvelopeVectors(t *testing.T) {
	for _, f := range frozenVectors {
		t.Run(f.name, func(t *testing.T) {
			canonical, e := canonical([]byte(f.raw))
			if e != nil || !bytes.Equal(canonical, []byte(f.raw)) {
				t.Fatalf("canonical mismatch: %v", e)
			}
			preimage, _ := hex.DecodeString(f.preimage)
			if !bytes.Equal(preimage, append([]byte("hn-artifact/1\x00"), canonical...)) {
				t.Fatal("signature preimage differs")
			}
			m := map[string]any{}
			if e := json.Unmarshal([]byte(f.raw), &m); e != nil {
				t.Fatal(e)
			}
			for _, k := range []string{"previous", "public_key", "request", "sequence", "stream", "timestamp"} {
				delete(m, k)
			}
			semantic, _ := json.Marshal(m)
			requestPreimage, _ := hex.DecodeString(f.requestPreimage)
			if !bytes.Equal(requestPreimage, append([]byte("hn-artifact-request-v1\x00"), semantic...)) {
				t.Fatal("request preimage differs")
			}
			v, e := Verify([]byte(f.raw), f.signature, nil)
			switch f.name {
			case "unknown-protocol":
				requireCode(t, e, "invalid_input")
			case "actor-key-mismatch":
				requireCode(t, e, "verification_failure")
			default:
				if e != nil || v.ID() != f.id || !bytes.Equal(v.Bytes(), canonical) {
					t.Fatalf("vector identity/signature: %s %v", v.ID(), e)
				}
			}
		})
	}
}
func TestEnvelopeTamperAndClosedFields(t *testing.T) {
	f := frozenVectors[0]
	_, e := Verify([]byte(f.raw), "A"+f.signature[1:], nil)
	requireCode(t, e, "verification_failure")
	_, e = Verify([]byte(strings.Replace(f.raw, "type-note-v1", "type-note-v2", 1)), f.signature, nil)
	requireCode(t, e, "verification_failure")
	for _, s := range []string{" " + f.raw, strings.Replace(f.raw, `"sequence":1`, `"sequence":1.0`, 1), strings.Replace(f.raw, `"sequence":1`, `"sequence":1,"unknown":0`, 1), strings.Replace(f.raw, `"sequence":1`, `"sequence":1,"sequence":1`, 1)} {
		_, e := Verify([]byte(s), f.signature, nil)
		requireCode(t, e, "invalid_input")
	}
	for _, mutation := range []func(map[string]any){
		func(m map[string]any) { m["actor"] = strings.Repeat("0", 64) }, func(m map[string]any) { m["stream"] = "sha256:" + strings.Repeat("0", 64) }, func(m map[string]any) { m["request"] = "sha256:" + strings.Repeat("0", 64) },
	} {
		raw, sig := signedFixture(t, mutation)
		_, e := Verify(raw, sig, nil)
		requireCode(t, e, "verification_failure")
	}
	for _, mutation := range []func(map[string]any){
		func(m map[string]any) { m["previous"] = "sha256:" + strings.Repeat("0", 64) }, func(m map[string]any) { m["sequence"] = 0 }, func(m map[string]any) { m["timestamp"] = "0000-01-01T00:00:00Z" }, func(m map[string]any) { m["timestamp"] = "2026-10-30T00:00:00.0Z" }, func(m map[string]any) { m["payload"].(map[string]any)["unknown"] = true },
	} {
		raw, sig := signedFixture(t, mutation)
		_, e := Verify(raw, sig, nil)
		requireCode(t, e, "invalid_input")
	}
}

// A fresh test-only seed independently produces counterexamples; it is never a
// production actor or a persisted key.
func signedFixture(t *testing.T, mutate func(map[string]any)) ([]byte, string) {
	t.Helper()
	m := map[string]any{}
	if e := json.Unmarshal([]byte(frozenVectors[0].raw), &m); e != nil {
		t.Fatal(e)
	}
	seed := sha256.Sum256([]byte("hn artifact WP03 test-only key"))
	key := ed25519.NewKeyFromSeed(seed[:])
	public := key.Public().(ed25519.PublicKey)
	sum := sha256.Sum256(public)
	actor := hex.EncodeToString(sum[:])
	m["actor"] = actor
	m["public_key"] = base64.RawStdEncoding.EncodeToString(public)
	m["stream"] = digest([]byte("hn-artifact-stream-v1\x00" + actor))
	mutate(m)
	semantic := map[string]any{}
	for _, k := range []string{"actor", "kind", "operation", "parents", "payload", "protocol", "record"} {
		semantic[k] = m[k]
	}
	b, _ := json.Marshal(semantic)
	// Preserve an intentionally wrong request rather than repairing that control.
	if m["request"] != "sha256:"+strings.Repeat("0", 64) {
		m["request"] = digest(append([]byte("hn-artifact-request-v1\x00"), b...))
	}
	raw, e := json.Marshal(m)
	if e != nil {
		t.Fatal(e)
	}
	sig := base64.RawStdEncoding.EncodeToString(ed25519.Sign(key, append([]byte("hn-artifact/1\x00"), raw...)))
	return raw, sig
}
func TestEnvelopePredecessor(t *testing.T) {
	first := frozenVectors[0]
	second := frozenVectors[1]
	v, e := Verify([]byte(first.raw), first.signature, nil)
	if e != nil {
		t.Fatal(e)
	}
	if _, e := Verify([]byte(second.raw), second.signature, &v); e != nil {
		t.Fatal(e)
	}
	wrong, e := Verify([]byte(second.raw), second.signature, nil)
	if e != nil {
		t.Fatal(e)
	}
	_, e = Verify([]byte(second.raw), second.signature, &wrong)
	requireCode(t, e, "invalid_history")
	_, e = Verify([]byte(second.raw), second.signature, &Verified{})
	requireCode(t, e, "invalid_history")
}
func TestEnvelopeOwnedBounds(t *testing.T) {
	for _, n := range []int{128, 129} {
		raw, sig := signedFixture(t, func(m map[string]any) { m["operation"] = strings.Repeat("x", n) })
		_, e := Verify(raw, sig, nil)
		if n == 128 && e != nil {
			t.Fatal(e)
		}
		if n == 129 {
			requireCode(t, e, "invalid_input")
		}
	}
	for _, n := range []int64{2147483647, 2147483648} {
		raw, sig := signedFixture(t, func(m map[string]any) { m["payload"].(map[string]any)["schema_version"] = n })
		_, e := Verify(raw, sig, nil)
		if n == 2147483647 && e != nil {
			t.Fatal(e)
		}
		if n == 2147483648 {
			requireCode(t, e, "invalid_input")
		}
	}
	for _, n := range []int{65536, 65537} {
		raw, sig := signedFixture(t, func(m map[string]any) {
			p := m["payload"].(map[string]any)
			schema := map[string]any{"padding": ""}
			base, _ := json.Marshal(schema)
			schema["padding"] = strings.Repeat("x", n-len(base))
			p["schema"] = schema
		})
		_, e := Verify(raw, sig, nil)
		if n == 65536 && e != nil {
			t.Fatal(e)
		}
		if n == 65537 {
			requireCode(t, e, "resource_limit")
		}
	}
	for _, n := range []int{8, 9} {
		fields := map[string]any{}
		current := fields
		for i := 1; i < n; i++ {
			next := map[string]any{}
			current["nest"] = next
			current = next
		}
		e := fieldBounds(fields, 1)
		if n == 8 && e != nil {
			t.Fatal(e)
		}
		if n == 9 {
			requireCode(t, e, "resource_limit")
		}
	}
}

// Run the simultaneous first validations in a fresh process: the other envelope
// tests must not warm the optional validators before this race check.
func TestEnvelopeConcurrentFirstUse(t *testing.T) {
	const child = "HN_ARTIFACT_CONCURRENT_FIRST_USE"
	if os.Getenv(child) != "1" {
		cmd := exec.Command(os.Args[0], "-test.run=^TestEnvelopeConcurrentFirstUse$", "-test.count=1")
		cmd.Env = append(os.Environ(), child+"=1")
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("fresh-process validation: %v\n%s", err, out)
		}
		return
	}

	// A signed list reaches all five grammars, including field and member names.
	raw, sig := signedFixture(t, func(m map[string]any) {
		m["kind"] = "record.open"
		m["payload"] = map[string]any{
			"shape": "list", "type_id": "example/list", "type_revision": frozenVectors[0].id,
			"title": "Concurrent first use", "content": "", "fields": map[string]any{"_field.key-1": true},
			"members":       []any{map[string]any{"member_id": "1.member-key_", "target": frozenVectors[0].id, "target_mode": "revision", "required": false}},
			"relationships": []any{}, "conversion_sources": []any{},
		}
	})
	start := make(chan struct{})
	var workers sync.WaitGroup
	for range 32 {
		workers.Go(func() {
			<-start
			v, err := Verify(raw, sig, nil)
			if err != nil || !bytes.Equal(v.Bytes(), raw) {
				t.Errorf("concurrent signed list: %v", err)
			}
			for _, f := range frozenVectors {
				v, err := Verify([]byte(f.raw), f.signature, nil)
				switch f.name {
				case "unknown-protocol":
					requireCode(t, err, "invalid_input")
				case "actor-key-mismatch":
					requireCode(t, err, "verification_failure")
				default:
					if err != nil || v.ID() != f.id || !bytes.Equal(v.Bytes(), []byte(f.raw)) {
						t.Errorf("concurrent frozen %s: %s %v", f.name, v.ID(), err)
					}
				}
			}
		})
	}
	close(start)
	workers.Wait()
}

func TestEnvelopeIdentifierGrammarRefusals(t *testing.T) {
	for _, tc := range []struct {
		name, message string
		mutate        func(map[string]any)
	}{
		{"actor", "actor must be a full lower-case fingerprint", func(m map[string]any) { m["actor"] = strings.Repeat("A", 64) }},
		{"digest", "sequence and previous disagree", func(m map[string]any) { m["sequence"] = 2; m["previous"] = "sha256:" + strings.Repeat("A", 64) }},
		{"type", "invalid or reserved type identifier", func(m map[string]any) { m["payload"].(map[string]any)["type_id"] = "example/name\n" }},
		{"field", "invalid field name", func(m map[string]any) { m["payload"].(map[string]any)["fields"] = map[string]any{"field\n": true} }},
		{"member", "invalid or duplicate collection member", func(m map[string]any) {
			m["payload"].(map[string]any)["members"] = []any{map[string]any{"member_id": "member\n", "target": frozenVectors[0].id, "target_mode": "revision", "required": false}}
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			raw, sig := signedFixture(t, func(m map[string]any) {
				m["kind"] = "record.open"
				m["payload"] = map[string]any{"shape": "list", "type_id": "example/list", "type_revision": frozenVectors[0].id, "title": "Grammar", "content": "", "fields": map[string]any{}, "members": []any{}, "relationships": []any{}, "conversion_sources": []any{}}
				tc.mutate(m)
			})
			_, err := Verify(raw, sig, nil)
			requireCode(t, err, "invalid_input")
			if err.Error() != "invalid_input: "+tc.message {
				t.Fatalf("changed grammar diagnostic: %v", err)
			}
		})
	}
}
